// Needs-you cards. SETUP: paste the data table id below.
const TABLE_ID = 'REPLACE_WITH_ACTIONS_TABLE_ID';
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
if (TABLE_ID.startsWith('REPLACE')) return fail('SETUP_ERROR', 'actions data table id is not set in Validate Input', 500);
const base = 'http://localhost:5678/api/v1/data-tables/' + TABLE_ID + '/rows';
const op = body.op;
if (!['put', 'list', 'get', 'answer', 'undo'].includes(op)) return fail('VALIDATION_ERROR', 'op must be put, list, get, answer or undo');
const idOk = (id) => typeof id === 'string' && /^[A-Za-z0-9:_-]{1,100}$/.test(id);
const byId = (id) => ({ type: 'and', filters: [{ columnName: 'card_id', condition: 'eq', value: id }] });
const now = new Date().toISOString();

if (op === 'put') {                         // the EA writes or refreshes a card
  const c = body.card;
  if (c == null || typeof c !== 'object' || Array.isArray(c)) return fail('VALIDATION_ERROR', 'card must be an object');
  if (!idOk(c.id)) return fail('VALIDATION_ERROR', 'card.id is required');
  if (typeof c.title !== 'string' || c.title.trim() === '') return fail('VALIDATION_ERROR', 'card.title is required');
  if (!['opts', 'quote', 'bill', 'section', 'parameter', 'triage', 'rule'].includes(c.kind)) return fail('VALIDATION_ERROR', 'card.kind is not a contract ActionKind');
  if (JSON.stringify(c).length > 100000) return fail('VALIDATION_ERROR', 'card is larger than 100 KB');
  const rank = Number.isFinite(c.rank) ? c.rank : 100;
  const expires = isIso(c.expiresAt) ? c.expiresAt : '';
  return [{ json: { valid: true, op, isPut: true, request_id, cardId: c.id, upsertUrl: base + '/upsert',
    upsertBody: { filter: byId(c.id), data: { card_id: c.id, state: 'open', card_json: JSON.stringify(c), rank, expires_at: expires, answer_json: '', undo_until: '', updated_at: now }, returnData: false } } }];
}
let filter, limit = 1, state;
if (op === 'list') {
  state = body.state === 'history' ? 'history' : 'open';
  filter = state === 'open'
    ? { type: 'and', filters: [{ columnName: 'state', condition: 'neq', value: 'answered' }] }
    : { type: 'and', filters: [{ columnName: 'state', condition: 'eq', value: 'answered' }] };
  limit = state === 'open' ? 250 : Math.max(1, Math.min(100, parseInt(body.limit ?? 50, 10) || 50));
} else {
  if (!idOk(body.id)) return fail('VALIDATION_ERROR', 'id is required');
  filter = byId(body.id);
}
let answer = null;
if (op === 'answer') {
  const VERBS = ['approve', 'revise', 'later', 'never', 'teach'];
  if (!VERBS.includes(body.verb)) return fail('VALIDATION_ERROR', 'verb must be one of ' + VERBS.join(', '));
  if (body.verb === 'revise' && (typeof body.revision !== 'string' || body.revision.trim() === '')) return fail('VALIDATION_ERROR', 'revise needs a revision');
  if (body.verb === 'teach' && (typeof body.rule !== 'string' || body.rule.trim() === '')) return fail('VALIDATION_ERROR', 'teach needs a rule');
  if (body.option != null && ![1, 2, 3].includes(body.option)) return fail('VALIDATION_ERROR', 'option must be 1, 2 or 3');
  if (body.until != null && !isIso(body.until)) return fail('VALIDATION_ERROR', 'until must be ISO 8601');
  answer = { verb: body.verb, option: body.option ?? null, revision: body.revision ?? null, rule: body.rule ?? null, until: body.until ?? null, via: body.via === 'telegram' ? 'telegram' : 'app' };
}
const url = base + '?limit=' + limit + '&sortBy=' + encodeURIComponent('updated_at:desc') + '&filter=' + encodeURIComponent(JSON.stringify(filter));
return [{ json: { valid: true, op, isPut: false, request_id, id: body.id, state, answer, updateUrl: base + '/update', req: { url } } }];

const v = $('Validate Input').first().json;
const r = $input.first().json || {};
const UNDO_SECONDS = 12;                              // app shows 10 s; 2 s grace for the round trip (N8N-11)
const OPEN_CAP = 5;                                   // CONTRACT.md §1.4
const err = (code, message, status_code) => [{ json: { ok: false, write: false, status_code, request_id: v.request_id, error: { code, message } } }];
if (!(r.statusCode >= 200 && r.statusCode < 300)) return err('UPSTREAM_ERROR', 'data table answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300), 502);
const rows = (r.body && Array.isArray(r.body.data)) ? r.body.data : [];
const parse = (s) => { if (!s) return null; try { return JSON.parse(s); } catch (e) { return null; } };
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const byId = (id) => ({ type: 'and', filters: [{ columnName: 'card_id', condition: 'eq', value: id }] });
function toItem(row) {
  const card = parse(row.card_json) || { id: row.card_id };
  const answer = parse(row.answer_json);
  const item = Object.assign({}, card, { state: row.state });
  if (answer) item.answer = answer;
  if (answer && answer.until) item.laterUntil = answer.until;
  if (row.undo_until) item.undoUntil = row.undo_until;
  return item;
}
const ok = (data) => [{ json: { ok: true, write: false, response: { ok: true, request_id: v.request_id, data } } }];
// Monday 08:00 Brisbane (UTC+10, no DST), the contract's default for "later"
function nextMonday8() {
  const b = new Date(nowMs + 10 * 3600000);
  let days = (8 - b.getUTCDay()) % 7; if (days === 0) days = 7;
  const t = Date.UTC(b.getUTCFullYear(), b.getUTCMonth(), b.getUTCDate() + days, 8, 0, 0) - 10 * 3600000;
  return new Date(t).toISOString();
}

if (v.op === 'list') {
  if (v.state === 'history') return ok({ items: rows.map(toItem) });
  const live = rows.filter((row) => {
    if (row.expires_at && Date.parse(row.expires_at) <= nowMs) return false;
    if (row.state === 'open') return true;
    if (row.state === 'later') { const a = parse(row.answer_json); return !!(a && a.until && Date.parse(a.until) <= nowMs); }
    return false;
  }).map((row) => Object.assign(toItem(row), { state: 'open' }));
  live.sort((a, b) => (a.rank ?? 100) - (b.rank ?? 100));
  return ok({ items: live.slice(0, OPEN_CAP), totalOpen: live.length });
}
const row = rows[0];
if (!row) return err('NOT_FOUND', 'card not found', 404);
if (v.op === 'get') return ok({ item: toItem(row) });

if (v.op === 'answer') {
  const live = row.state === 'open' || (row.state === 'later');
  if (!live) return err('CONFLICT', 'card is already ' + row.state, 409);
  const answer = Object.assign({}, v.answer, { at: nowIso });
  if (answer.verb === 'later' && !answer.until) answer.until = nextMonday8();
  const newState = answer.verb === 'later' ? 'later' : 'answered';
  const undoUntil = new Date(nowMs + UNDO_SECONDS * 1000).toISOString();
  const card = parse(row.card_json) || {};
  const item = Object.assign({}, card, { state: newState, answer, undoUntil });
  if (answer.until) item.laterUntil = answer.until;
  const data = { item, undoUntil };
  if (answer.verb === 'approve' && card.kind === 'quote') data.status = 'outbox_user_sends';
  return [{ json: { ok: true, write: true, updateUrl: v.updateUrl,
    updateBody: { filter: byId(row.card_id), data: { state: newState, answer_json: JSON.stringify(answer), undo_until: undoUntil, updated_at: nowIso }, returnData: false },
    response: { ok: true, request_id: v.request_id, data } } }];
}
// undo, inside the 10-second window only (CONTRACT.md §4.3: after it, 409)
if (row.state === 'open' || !row.undo_until) return err('CONFLICT', 'nothing to undo', 409);
if (Date.parse(row.undo_until) < nowMs) return err('UNDO_EXPIRED', 'the undo window has passed', 409);
const card = parse(row.card_json) || {};
return [{ json: { ok: true, write: true, updateUrl: v.updateUrl,
  updateBody: { filter: byId(row.card_id), data: { state: 'open', answer_json: '', undo_until: '', updated_at: nowIso }, returnData: false },
  response: { ok: true, request_id: v.request_id, data: { item: Object.assign({}, card, { state: 'open' }) } } } }];

// The write only counts if the data table said so.
const d = $('Decide').first().json;
const r = $input.first().json || {};
if (r.statusCode >= 200 && r.statusCode < 300) return [{ json: { ok: true, response: d.response } }];
return [{ json: { ok: false, status_code: 502, request_id: d.response && d.response.request_id, error: { code: 'UPSTREAM_ERROR', message: 'data table write answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300) } } }];

const v = $('Validate Input').first().json;
const r = $input.first().json || {};
if (r.statusCode >= 200 && r.statusCode < 300) return [{ json: { ok: true, response: { ok: true, request_id: v.request_id, data: { id: v.cardId, state: 'open' } } } }];
return [{ json: { ok: false, status_code: 502, request_id: v.request_id, error: { code: 'UPSTREAM_ERROR', message: 'data table answered ' + r.statusCode + ': ' + JSON.stringify(r.body || '').slice(0, 300) } } }];
